do.text:
SFT('lab: active ' + IsScriptActive('TowBeam'));
SFT('lab: info ' + (ShipFindCustomShipInfoByType(Player(), 'TowBeam_Info') >= 0));
SFT('lab: onplanet ' + int(GetShipPlanet(Player())) + ' inspace ' + ShipInNormalSpace(Player()));
SFT('lab: state ' + RunFunctionFromScript('TowBeam', 'State'));

dword pl;
dword st;
dword it;
pl = Player();
st = ShipStar(pl);
it = CreateGoods(t_Minerals, 150);
DropItemInSystem(st, it, CoordX(pl) + 80, CoordY(pl));
SFT('lab: item ' + Id(it) + ' w=' + ItemSize(it) + ' in=' + ItemIn(it, st) + ' script=' + ItemInScript(it));
SFT('lab: before speed=' + ShipSpeed(pl) + ' bonmass=' + ShipSpecialBonuses(pl, bonMass) + ' block=' + ShipStatusEffect(pl, 3));
SFT('lab: hold free=' + ShipFreeSpace(pl) + ' goods=' + GoodsAdd(pl, t_Minerals, 150));
ShipCalcParam(pl);
SFT('lab: hold speed=' + ShipSpeed(pl) + ' free=' + ShipFreeSpace(pl));
GoodsAdd(pl, t_Minerals, -150);
ShipCalcParam(pl);
SFT('lab: hold emptied speed=' + ShipSpeed(pl) + ' free=' + ShipFreeSpace(pl));
SFT('lab: check ' + RunFunctionFromScript('TowBeam', 'Target', it, 0));
SFT('lab: target ' + RunFunctionFromScript('TowBeam', 'Target', it, 1));
SFT('lab: after speed=' + ShipSpeed(pl) + ' bonmass=' + ShipSpecialBonuses(pl, bonMass) + ' block=' + ShipStatusEffect(pl, 3) + ' script=' + ItemInScript(it));
SFT('lab: state ' + RunFunctionFromScript('TowBeam', 'State'));

dword pl;
dword it;
pl = Player();
it = CreateEquipment(t_Engine, 60, 1, Maloc);
DropItemInSystem(ShipStar(pl), it, CoordX(pl) - 60, CoordY(pl) + 40);
SFT('lab: second ' + RunFunctionFromScript('TowBeam', 'Target', it, 1) + ' w=' + ItemSize(it));
SFT('lab: state ' + RunFunctionFromScript('TowBeam', 'State'));

dword it;
it = IdToItem(int(GetParFromString(GetParFromString(RunFunctionFromScript('TowBeam', 'State'), ' ', 1, 0), ',', 1, 0)));
SFT('lab: release ' + RunFunctionFromScript('TowBeam', 'Target', it, 1) + ' script=' + ItemInScript(it));
SFT('lab: state ' + RunFunctionFromScript('TowBeam', 'State'));

RunFunctionFromScript('TowBeam', 'Key', 1);
SFT('lab: state ' + RunFunctionFromScript('TowBeam', 'State') + ' bonmass=' + ShipSpecialBonuses(Player(), bonMass) + ' block=' + ShipStatusEffect(Player(), 3));
SFT('lab: unblock ' + ShipStatusEffect(Player(), 3));

dword pl;
dword it;
pl = Player();
it = CreateGoods(t_Minerals, 120);
DropItemInSystem(ShipStar(pl), it, CoordX(pl) + 70, CoordY(pl));
SFT('lab: attach ' + RunFunctionFromScript('TowBeam', 'Target', it, 1));
ItemIsInUse(ShipEqInSlot(pl, t_CargoHook), pl, 0);
SFT('lab: hook off ' + int(ShipEqInSlot(pl, t_CargoHook)));

SFT('lab: state ' + RunFunctionFromScript('TowBeam', 'State'));
dword pl;
dword hook;
int i;
pl = Player();
for (i = 1; i < ShipItems(pl); i = i + 1) {
  if (ItemType(ShipItems(pl, i)) == t_CargoHook) {
    hook = ShipItems(pl, i);
  }
}
ItemIsInUse(hook, pl, 1);
SFT('lab: hook back ' + int(ShipEqInSlot(pl, t_CargoHook)));

dword pl;
dword st;
dword it;
dword p;
dword best;
int i;
float d;
float bd;
pl = Player();
st = ShipStar(pl);
bd = 1000000;
for (i = 0; i < StarPlanets(st); i = i + 1) {
  p = StarPlanets(st, i);
  if (PlanetOwner(p) != None) {
    d = Dist(pl, p);
    if (d < bd) {
      bd = d;
      best = p;
    }
  }
}
it = CreateGoods(t_Minerals, 100);
DropItemInSystem(st, it, CoordX(pl) + 70, CoordY(pl));
SFT('lab: attach ' + RunFunctionFromScript('TowBeam', 'Target', it, 1) + ' planet=' + Name(best) + ' dist=' + round(bd));
OrderLanding(pl, best);

dword pl;
pl = Player();
SFT('lab: landed ' + int(GetShipPlanet(pl)) + ' storage_before=' + StorageItems());
RunFunctionFromScript('TowBeam', 'Form');
SFT('lab: storage_after=' + StorageItems() + ' state ' + RunFunctionFromScript('TowBeam', 'State'));

dword pl;
dword it;
dword other;
pl = Player();
it = CreateGoods(t_Minerals, 110);
DropItemInSystem(ShipStar(pl), it, CoordX(pl) + 70, CoordY(pl));
SFT('lab: attach ' + RunFunctionFromScript('TowBeam', 'Target', it, 1) + ' star=' + Name(ShipStar(pl)));
other = StarNearbyStars(ShipStar(pl), 1);
SFT('lab: jump to ' + Name(other));
OrderJump(pl, other);
